{"label":"Route callback signature changed","sha":"75661a2266bbf25480be56960513cf9405ba3ba9","short":"75661a22","date":"2010-07-26T13:29:16-07:00","author":"Tj Holowaychuk","email":"tj@vision-media.ca","kind":"other","files":0,"add":0,"del":0,"body":"it is now like Express used to be: (req, res, next)
