will still work"}

{"label":"expose err.view when failing to locate a view","sha":"e71696cf34e5153bf3db5dbca4ca5a7625cd3215","short":"e71696cf","date":"2011-03-28T14:44:12-07:00","author":"Tj Holowaychuk","email":"tj@vision-media.ca","kind":"other","files":1,"add":3,"del":1,"body":"allows for:

   err.view.path

etc"}

{"label":"Added `req.route`, exposing the current route. Closes #11","sha":"91997e9c53db057667981d5f5ece6eb15a8d1059","short":"91997e9c","date":"2011-05-27T09:12:49-07:00","author":"Tj Holowaychuk","email":"tj@vision-media.ca","kind":"other","files":2,"add":23,"del":1,"body":"this can be used with a dynamicHelper to expose the _last_
route that was matched, aka the end-point when rendering a template.

this is a `Route` instance, so it has .path, .regexp, etc."}

{"label":"Added "strict routing" setting for trailing slashes","sha":"6f7075be740c26c4c1f3c3e8df4c3472e4907561","short":"6f7075be","date":"2011-06-29T16:35:49-07:00","author":"Tj Holowaychuk","email":"tj@vision-media.ca","kind":"performance","files":4,"add":35,"del":6,"body":"for people who are:

  a) over-optimizing seo
  b) working on fs-like APIs"}

{"label":"Added req.fresh and req.stale","sha":"0e4e050b2177e503c3d7a4e0ac823b682e3956a1","short":"0e4e050b","date":"2011-10-13T09:43:31-07:00","author":"Tj Holowaychuk","email":"tj@vision-media.ca","kind":"other","files":1,"add":27,"del":0,"body":"lame usage example:

app.get('/user/:id', function(req, res){
  var id = req.params.id;

  res.set('ETag', 'user-' + id);

  if (req.fresh) return res.send(304);
  setTimeout(function(){
    res.send('large expensive user response ' + id);
  }, 2000);
});"}

{"label":"Add full extname support to the "view engine" setting; e.g., ".jade".","sha":"0fdceb3de379923ea8087b1f1cc9e6382e6ef41d","short":"0fdceb3d","date":"2013-01-10T21:41:24-05:00","author":"Eric Ferraiuolo","email":"eferraiuolo@gmail.com","kind":"feature","files":1,"add":1,"del":1,"body":"This allows View to support a `defaultEngine` (a.k.a. an app's
"view engine" setting) which contains a ".", for example:

```
app.engine('.jade', jadeEngine);
app.set('view engine', '.jade');
```

This brings View's handling of template filename extensions to parity
with `app.engine()`.

This allows an app's "view engine" setting to be a full extension name,
including the "."."}

